import numpy as np

def problem(x: np.ndarray) -> float:
    """A 2D synthetic benchmark function designed to mimic target ELA features. It combines polynomial and rational terms.
    Formula: f(x) = 0.001 * ( x[0]**2 + 0.5*x[1]**2 + x[0]*x[1] + 0.2*x[0]**3) +  1 / (1 + 0.1*(x[0]**2 + x[1]**2)) + 0.01*np.sin(4*x[1])
    """
    return 0.001 * ( x[0]**2 + 0.5*x[1]**2 + x[0]*x[1] + 0.2*x[0]**3) +  1 / (1 + 0.1*(x[0]**2 + x[1]**2)) + 0.01*np.sin(4*x[1])
